<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Reação Transfusional</title><style>@page{size:A4;margin:14mm}body{font:12px Arial;color:#17212b}header{border-bottom:3px solid #7f1d35;text-align:center;margin-bottom:20px}h1{font-size:18px;letter-spacing:.08em}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.grid div,.result,.history article{border:1px solid #ccd3dc;border-radius:6px;padding:10px}.grid b,.history small{display:block;font-size:9px;text-transform:uppercase;color:#687386;margin-bottom:5px}.history{margin-top:18px}.history h2{font-size:14px}.history article{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-top:7px}.history strong{grid-column:1/-1}.result{margin-top:18px;min-height:120px}.sign{margin-top:60px;border-top:1px solid #333;width:55%;text-align:center;padding-top:5px}.print{position:fixed;right:12px;top:12px}@media print{.print{display:none}}</style></head><body><button class="print" onclick="print()">Imprimir</button><header><h1>REAÇÃO TRANSFUSIONAL</h1><p>Formulário de trabalho — Bacteriológico individual</p></header><section class="grid"><div><b>Paciente</b><?=htmlspecialchars((string)$sample['patient_name'])?></div><div><b>Nº da doação</b><?=htmlspecialchars((string)$sample['donation_number'])?></div><div><b>Hemocomponente</b><?=htmlspecialchars($sample['component_code'].' — '.$sample['component_name'])?></div><div><b>Código LCQH</b><?=htmlspecialchars((string)($sample['lcqh_code']?:'—'))?></div><div><b>Origem</b><?=htmlspecialchars((string)($sample['origin_name']?:'—'))?></div><div><b>Recebimento</b><?=$sample['received_at']?date('d/m/Y H:i',strtotime($sample['received_at'])):'—'?></div></section><?php if($tests):?><section class="history"><h2>Histórico dos testes</h2><?php foreach($tests as$t):?><article><strong>Teste <?=(int)$t['test_sequence']?><?=$t['test_kind']==='additional'?' — adicional':''?></strong><span><small>Data</small><?=date('d/m/Y H:i',strtotime($t['performed_at']))?></span><span><small>Resultado</small><?=$t['result']==='positive'?'Positivo':($t['result']==='negative'?'Negativo':'Em análise')?></span><span><small>Bactéria</small><?=htmlspecialchars((string)($t['identified_bacteria']?:'—'))?></span></article><?php endforeach;?></section><?php endif;?><div class="result"><b>Registro manual</b><p>☐ Negativo &nbsp;&nbsp;&nbsp; ☐ Positivo</p><p>Bactéria identificada: ______________________________________________</p><p>Observações:</p></div><div class="sign">Responsável / data e hora</div></body></html>
